// Obtenemos los datos del usuario directamente desde el nodo Get a row original
const usuario = $('Get a row').first().json;
const token = usuario.access_token;
const plan = usuario.plan || 'FREE';
const sectoresGuardados = usuario.sectores || [];

// Lista completa de todos los sectores disponibles
const todosLosSectores = [
    "Tecnología y Telecomunicaciones",
    "Salud y Farmacéutica",
    "Construcción y Obra Civil",
    "Alimentos y Agro",
    "Transporte y Repuestos",
    "Servicios Generales y Mantenimiento",
    "Oficina y Uniformes",
    "Consultoría e Ingeniería",
    "Maquinaria y Equipos Industriales"
];

// Si es FREE y no tiene sectores guardados previamente, marcamos todos por defecto
let sectoresActivos = sectoresGuardados;
if (plan === 'FREE' && (!sectoresGuardados || sectoresGuardados.length === 0)) {
    sectoresActivos = todosLosSectores;
}

// Generamos el HTML de los checkboxes de forma dinámica
let checkboxesHTML = todosLosSectores.map(sector => {
    const isChecked = sectoresActivos.includes(sector) ? 'checked' : '';
    return `
        <label class="checkbox-item">
            <input type="checkbox" name="sectores" value="${sector}" ${isChecked}>
            <span>${sector}</span>
        </label>
    `;
}).join('');

// HTML completo de la página de preferencias
const htmlResponse = `<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Selección de Sectores - Licitaciones Venezuela</title>
    <link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>=Ë</text></svg>">
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background-color: #f3f4f6; display: flex; justify-content: center; align-items: center; min-height: 100vh; margin: 0; padding: 20px; box-sizing: border-box; }
        .card { background: #ffffff; padding: 32px; border-radius: 12px; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); width: 100%; max-width: 480px; }
        h2 { color: #111827; font-size: 20px; margin-top: 0; margin-bottom: 8px; }
        p { color: #6b7280; font-size: 14px; margin-bottom: 20px; }
        .checkbox-container { display: flex; flex-direction: column; gap: 12px; max-height: 300px; overflow-y: auto; margin-bottom: 20px; padding-right: 4px; }
        .checkbox-item { display: flex; align-items: center; gap: 10px; font-size: 14px; color: #374151; cursor: pointer; }
        .checkbox-item input { width: 18px; height: 18px; accent-color: #2563eb; cursor: pointer; }
        button { background-color: #2563eb; color: white; border: none; width: 100%; padding: 12px; border-radius: 8px; font-size: 15px; font-weight: 500; cursor: pointer; transition: background 0.2s; }
        button:hover { background-color: #1d4ed8; }
        .plan-badge { display: inline-block; background: #dbeafe; color: #1e40af; font-size: 12px; padding: 4px 8px; border-radius: 4px; font-weight: 600; margin-bottom: 12px; }
    </style>
</head>
<body>
    <div class="card">
        <span class="plan-badge">Plan: ${plan}</span>
        <h2>Configura tus sectores de interés</h2>
        <p>Selecciona los sectores sobre los cuales deseas recibir notificaciones en tu boletín.</p>

        <form action="/webhook/preferencias/salvar" method="POST">
            <input type="hidden" name="token" value="${token}">
            <div class="checkbox-container">
                ${checkboxesHTML}
            </div>
            <button type="submit">Guardar Preferencias</button>
        </form>
    </div>
</body>
</html>`;

return { json: { html: htmlResponse } };

const body = $json.body;

return {
    json: {
        token: body.token,
        sectores: body.sectores || []
    }
};

parameters.query:
UPDATE usuarios 
SET sectores = ARRAY[{{ $json.sectores && $json.sectores.length > 0 ?$json.sectores.map(s => `'` + s.replace(/'/g, "''") + `'`).join(', ') : '' }}]::text[] 
WHERE access_token = '{{ $json.token }}';

